function Proses(x : integer) : integer;
begin
 if(x <= 1) then Proses := x
 else Proses := Proses(x div 2 * x mod 2) + Proses(x div 2 + x mod 2);
end;

function noan(n : integer) : integer;
begin
 if(n < 4) then noan := n
 else noan := noan(n-1) + noan(n-2) + noan(n-4);
end;

